on conflict (slug) do update set titre = excluded.titre, titre_en = excluded.titre_en, sous_titre = excluded.sous_titre, sous_titre_en = excluded.sous_titre_en, peuple = excluded.peuple, peuple_en = excluded.peuple_en, region = excluded.region, region_en = excluded.region_en, zone = excluded.zone, zone_en = excluded.zone_en, epoque = excluded.epoque, epoque_en = excluded.epoque_en, type_contenu = excluded.type_contenu, theme = excluded.theme, theme_en = excluded.theme_en, recit_chapitres_fr = excluded.recit_chapitres_fr, recit_chapitres_en = excluded.recit_chapitres_en, sources = excluded.sources, couleur = excluded.couleur, ordre_affichage = excluded.ordre_affichage, fichier_source = excluded.fichier_source, statut_publication = excluded.statut_publication, updated_at = now();

commit;

-- Contrôle
select slug, titre, zone, jsonb_array_length(recit_chapitres_fr) as chap_fr, jsonb_array_length(recit_chapitres_en) as chap_en, cardinality(sources) as nb_sources, statut_publication
from public.mythes order by ordre_affichage, slug;
